S=E['comparison']; A=S['baseline']['estimates']; B=S['candidate']['estimates']; D=S['delta']; T=E['stressed']['candidate']['estimates']
def num(x,n=1):return f'{x:,.{n}f}'.replace(',','\u00a0').replace('.',',')
def pc(x):return num(x*100)+'%'
def mean(x,k):return x[k]['mean']
def ci(x,k,scale=1):return num(x[k]['ci95Low']*scale)+' ... '+num(x[k]['ci95High']*scale)
styles={
 'body':ParagraphStyle('Body',fontName='Arial',fontSize=10.5,leading=15.1,spaceAfter=9,textColor=colors.HexColor('#172330')),
 'small':ParagraphStyle('Small',fontName='Arial',fontSize=9,leading=12.5,spaceAfter=7,textColor=colors.HexColor('#526171')),
 'h1':ParagraphStyle('H1',fontName='ArialBold',fontSize=20,leading=24,spaceAfter=16,textColor=colors.black,keepWithNext=True),
 'h2':ParagraphStyle('H2',fontName='ArialBold',fontSize=12,leading=16,spaceBefore=11,spaceAfter=7,textColor=colors.black,keepWithNext=True),
 'title':ParagraphStyle('Title',fontName='ArialBold',fontSize=35,leading=40,spaceAfter=20,textColor=colors.black),
 'cell':ParagraphStyle('Cell',fontName='Arial',fontSize=9,leading=12,textColor=colors.HexColor('#172330')),
 'th':ParagraphStyle('TH',fontName='ArialBold',fontSize=9,leading=12,textColor=colors.white),
 'caption':ParagraphStyle('Caption',fontName='Arial',fontSize=9,leading=12,spaceBefore=6,spaceAfter=12,textColor=colors.HexColor('#526171')),
}
W=A4[0]-96; story=[]; md=[]
def clean(s):return str(s).replace('\u2011','-').replace('\u2013','-').replace('\u2212','-')
def P(s,kind='body'):
 s=clean(s);story.append(Paragraph(s,styles[kind]));md.append(re.sub('<[^>]+>','',s)+'\n')
def H(s):P(s,'h2')
def page(title):
 if story:story.append(PageBreak())
 P(title,'h1');md.append('\n')
def table(headers,rows,widths):
 if widths==[.65,1.1,2.45]:widths=[.7,1.4,2.5]
 cells=[[Paragraph(html.escape(clean(v)),styles['th']) for v in headers]]
 cells += [[Paragraph(html.escape(clean(v)).replace('\n','<br/>'),styles['cell']) for v in row] for row in rows]
 t=Table(cells,colWidths=[W*x/sum(widths) for x in widths],repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#153E65')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('GRID',(0,0),(-1,-1),.45,colors.HexColor('#D9D9D9')),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F2F6FA')])]))
 story.extend([t,Spacer(1,12)])
 md.append('| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(clean(v).replace('\n','; ') for v in r)+' |' for r in rows)+'\n')
def diagram(name,caption,maxh=450):
 path=ROOT/'docs'/'diagrams'/f'{name}.png'; im=PILImage.open(path); scale=min(W/im.width,maxh/im.height)
 story.append(Image(str(path),width=im.width*scale,height=im.height*scale,hAlign='CENTER'));P(caption,'caption')
 md.append(f'![{caption}](diagrams/{name}.svg)\n')
def source(label,url):P(f'<b>{html.escape(label)}</b><br/><link href="{html.escape(url)}" color="#1667AC">{html.escape(url)}</link>','small')

